\BT\label{th-RateG}
For any $k \geq 0$ we have
\beq\label{eq-RateG}
\ba{rcl}
\eta(x_{k+1})
& \, \leq \, &
\|F'(x_{k + 1}) \|_{*}
\; \leq \;
{L_p + H \over p!} \left[ {1 \over
	\sigma_q} \, \eta(x_k) \right]^{p \over q-1}.
\ea
\eeq
\ET

