\BL\label{lm-DecF}
Let $\beta > 1$ and $H = \beta L_p$. Then
\beq\label{eq-DecFB}
\ba{rcl}
\la F'(T), x - T \ra & \geq & \left( {p! \over (p+1)L_p}
\right)^{1 \over p} \cdot \| F'(T) \|_*^{p+1 \over p}
\cdot {(\beta^2 - 1)^{p-1 \over 2p} \over \beta} \cdot {p
	\over (p^2-1)^{p-1 \over 2p}}.
\ea
\eeq
In particular, if $\beta = p$, then
\beq\label{eq-DecF}
\ba{rcl}
\la F'(T), x - T \ra & \geq & \left( {p! \over (p+1)L_p}
\right)^{1 \over p} \cdot \| F'(T) \|_*^{p+1 \over p}.
\ea
\eeq
\EL

